// Scope types with a scope-id picker, in the uppercase spelling of the retired
// `RBACElementType` enum; managers >= 26.9.0 report them lowercase.
export const RBAC_ELEMENT_TYPES: ReadonlyArray<string> = [
  // Scope ID select implemented
  'DOMAIN',
  'PROJECT',
  'USER',
  'VFOLDER',
  'RESOURCE_GROUP',
  'SESSION',
  'MODEL_DEPLOYMENT',
  'CONTAINER_REGISTRY',
  'STORAGE_HOST',
  'KEYPAIR',
  // TODO: Scope ID select to be implemented in separate stacks
  // 'IMAGE',
  // 'ARTIFACT',
  // 'ARTIFACT_REGISTRY',
  // 'ARTIFACT_REVISION',
  // 'RESOURCE_PRESET',
  // 'USER_RESOURCE_POLICY',
  // 'KEYPAIR_RESOURCE_POLICY',
  // 'PROJECT_RESOURCE_POLICY',
  // 'ROLE',
  // TODO: No management UI in WebUI yet
  // 'DEPLOYMENT',
  // 'NOTIFICATION_CHANNEL',
  // 'NETWORK',
  // 'SESSION_TEMPLATE',
  // 'APP_CONFIG',
  // 'AUDIT_LOG',
  // 'EVENT_LOG',
  // 'NOTIFICATION_RULE',
];

/**
 * PILOT-DECISION P3C-4: this used to `extend SelectProps` (antd) and spread the
 * whole antd prop bag into ten different selects. The Astryx siblings do not
 * take antd props, so the router now declares the narrow contract its two call
 * sites actually use — the rest is what `Form.Item` injects.
 */
interface ScopeIdSelectProps {
  scopeType?: string;
  /** Injected by `Form.Item`. */
  value?: string;
  onChange?: (value: string | Array<string> | undefined) => void;
  placeholder?: string;
  isDisabled?: boolean;
}

/** Every branch renders inside a `Form.Item` that prints its own label. */
type ScopeIdBranchProps = Omit<ScopeIdSelectProps, 'scopeType'> & {
  label: string;
  isLabelHidden?: boolean;
};

const ResourceGroupScopeIdSelect: React.FC<ScopeIdBranchProps> = (props) => {
  'use memo';
  const queryRef = useLazyLoadQuery<RoleFormModalResourceGroupQuery>(
    graphql`
      query RoleFormModalResourceGroupQuery {
        ...BAIAdminResourceGroupSelect_resourceGroupsFragment
      }
    `,
    {},
    { fetchPolicy: 'store-and-network' },
  );
  return <BAIAdminResourceGroupSelect queryRef={queryRef} {...props} />;
};

/** True for the DOMAIN scope, whose id is the signed-in domain and is never shown. */
export const isDomainScopeType = (scopeType?: string) =>
  scopeType?.toUpperCase() === 'DOMAIN';

type DomainScopeIdProps = Pick<ScopeIdSelectProps, 'value' | 'onChange'>;

/** Hands `scopeId` to the form once it is known and differs from `value`. */
const useSyncScopeId = (
  scopeId: string | undefined,
  { value, onChange }: DomainScopeIdProps,
) => {
  useEffect(() => {
    if (scopeId && value !== scopeId) onChange?.(scopeId);
  }, [scopeId, value, onChange]);
};

/**
 * Fills the DOMAIN scope id with the signed-in domain's uuid (BA-7234): the
 * WebUI has no domain picker.
 */
const CurrentDomainScopeId: React.FC<DomainScopeIdProps> = (props) => {
  'use memo';
  const baiClient = useSuspendedBackendaiClient();
  const domainName: string = baiClient._config.domainName;
  const { domainV2 } = useLazyLoadQuery<RoleFormModalCurrentDomainQuery>(
    graphql`
      query RoleFormModalCurrentDomainQuery($domainName: String!) {
        domainV2(domainName: $domainName) {
          entityId
        }
      }
    `,
    { domainName },
    { fetchPolicy: 'store-or-network' },
  );
  useSyncScopeId(domainV2?.entityId, props);
  return null;
};

export const ScopeIdSelect: React.FC<ScopeIdSelectProps> = ({
  scopeType: rawScopeType,
  ...selectProps
}) => {
  'use memo';
  const { t } = useTranslation();
  const scopeType = rawScopeType?.toUpperCase();
  // The surrounding `Form.Item` already prints "Scope ID", so the Astryx
  // field's own label is the accessible name only.
  const branchProps: ScopeIdBranchProps = {
    ...selectProps,
    label: t('rbac.ScopeId'),
    isLabelHidden: true,
  };
  const fallback = (
    <AstryxFormSelector
      label={t('rbac.ScopeId')}
      placeholder={selectProps.placeholder}
      isLoading
      disabled
      options={[]}
    />
  );
  if (scopeType === 'DOMAIN') {
    return (
      <Suspense fallback={null}>
        <CurrentDomainScopeId
          value={selectProps.value}
          onChange={selectProps.onChange}
        />
      </Suspense>
    );
  }
  if (scopeType === 'PROJECT') {
    return (
      <Suspense fallback={fallback}>
        <BAIAdminProjectSelect {...branchProps} />
      </Suspense>
    );
  }
  if (scopeType === 'USER') {
    return (
      <Suspense fallback={fallback}>
        <BAIUserSelect valuePropName="id" {...branchProps} />
      </Suspense>
    );
  }
  if (scopeType === 'VFOLDER') {
    return (
      <Suspense fallback={fallback}>
        <BAIVFolderSelect {...branchProps} />
      </Suspense>
    );
  }
  if (scopeType === 'SESSION') {
    return (
      <Suspense fallback={fallback}>
        <BAIAdminSessionSelect {...branchProps} />
      </Suspense>
    );
  }
  if (scopeType === 'MODEL_DEPLOYMENT') {
    return (
      <Suspense fallback={fallback}>
        <BAIAdminModelServiceSelect {...branchProps} />
      </Suspense>
    );
  }
  if (scopeType === 'CONTAINER_REGISTRY') {
    return (
      <Suspense fallback={fallback}>
        <BAIAdminContainerRegistrySelect
          valuePropName="row_id"
          {...branchProps}
        />
      </Suspense>
    );
  }
  if (scopeType === 'STORAGE_HOST') {
    return (
      <Suspense fallback={fallback}>
        <BAIStorageHostSelect {...branchProps} />
      </Suspense>
    );
  }
  if (scopeType === 'KEYPAIR') {
    return (
      <Suspense fallback={fallback}>
        <BAIKeypairSelect {...branchProps} />
      </Suspense>
    );
  }
  if (scopeType === 'RESOURCE_GROUP') {
    return (
      <Suspense fallback={fallback}>
        <ResourceGroupScopeIdSelect {...branchProps} />
      </Suspense>
    );
  }
  // No scope type picked yet: an inert, empty field.
  return (
    <AstryxFormSelector
      label={t('rbac.ScopeId')}
      placeholder={selectProps.placeholder}
      value={selectProps.value}
      disabled
      options={[]}
    />
  );
};

interface RoleFormModalProps extends BAIModalProps {
  roleNodeFrgmt?: RoleFormModalFragment$key | null;
  onRequestClose: (success: boolean) => void;
}

const RoleFormModal: React.FC<RoleFormModalProps> = ({
  roleNodeFrgmt,
  onRequestClose,
  ...baiModalProps
}) => {
  'use memo';
  const { t } = useTranslation();
  const { message } = App.useApp();
  const { logger } = useBAILogger();
  const [form] = Form.useForm();
  const scopeType = Form.useWatch('scopeType', form) as string | undefined;

  const { rbacPermissionMatrix } =
    useLazyLoadQuery<RoleFormModalPermissionMatrixQuery>(
      graphql`
        query RoleFormModalPermissionMatrixQuery {
          rbacPermissionMatrix {
            scopeType
          }
        }
      `,
      {},
      { fetchPolicy: 'store-and-network' },
    );

  // The scope types the manager reports, in its own spelling, that have a
  // scope-id picker.
  const scopeTypeOptions = _.uniqBy(
    (rbacPermissionMatrix ?? []).filter((combination) =>
      RBAC_ELEMENT_TYPES.includes(combination.scopeType.toUpperCase()),
    ),
    (combination) => combination.scopeType.toUpperCase(),
  ).map((combination) => ({
    value: combination.scopeType,
    label: t(rbacTypeI18nKey(combination.scopeType), {
      defaultValue: combination.scopeType,
    }),
  }));

  const editingRole = useFragment(
    graphql`
      fragment RoleFormModalFragment on Role {
        id
        entityId
        name
        description
        autoAssign
      }
    `,
    roleNodeFrgmt ?? null,
  );

  const isEditMode = !!editingRole;

  const [commitCreateRole, isInFlightCreateRole] =
    useMutation<RoleFormModalCreateMutation>(graphql`
      mutation RoleFormModalCreateMutation($input: CreateRoleInput!) {
        adminCreateRole(input: $input) {
          id
          name
          description
          source
          status
          autoAssign
          createdAt
          updatedAt
        }
      }
    `);

  const [commitUpdateRole, isInFlightUpdateRole] =
    useMutation<RoleFormModalUpdateMutation>(graphql`
      mutation RoleFormModalUpdateMutation($input: UpdateRoleInput!) {
        adminUpdateRole(input: $input) {
          id
          name
          description
          autoAssign
          updatedAt
        }
      }
    `);

  const isDuplicateError = (errorMessage: string) => {
    return (
      errorMessage.includes('409') ||
      errorMessage.toLowerCase().includes('duplicate') ||
      errorMessage.toLowerCase().includes('already exists')
    );
  };

  const handleOk = () => {
    return form
      .validateFields()
      .then((values) => {
        if (isEditMode && editingRole) {
          const changedFields: {
            name?: string;
            description?: string | null;
            autoAssign?: boolean;
          } = {};
          if (values.name !== editingRole.name) {
            changedFields.name = values.name;
          }
          if (
            (values.description || null) !== (editingRole.description || null)
          ) {
            changedFields.description = values.description || null;
          }
          if (values.autoAssign !== editingRole.autoAssign) {
            changedFields.autoAssign = values.autoAssign;
          }

          if (Object.keys(changedFields).length === 0) {
            onRequestClose(false);
            return;
          }

          commitUpdateRole({
            variables: {
              input: {
                id: editingRole.entityId,
                ...changedFields,
              },
            },
            onCompleted: (_data, errors) => {
              if (errors && errors.length > 0) {
                const errorMessage = errors[0]?.message || '';
                if (isDuplicateError(errorMessage)) {
                  form.setFields([
                    {
                      name: 'name',
                      errors: [t('rbac.DuplicateRoleName')],
                    },
                  ]);
                  return;
                }
                logger.error(errors[0]);
                message.error(errorMessage || t('general.ErrorOccurred'));
                return;
              }
              message.success(t('rbac.RoleUpdated'));
              onRequestClose(true);
            },
            onError: (error) => {
              const errorMessage = error?.message || '';
              if (isDuplicateError(errorMessage)) {
                form.setFields([
                  { name: 'name', errors: [t('rbac.DuplicateRoleName')] },
                ]);
              } else {
                logger.error(error);
                message.error(errorMessage || t('general.ErrorOccurred'));
              }
            },
          });
        } else {
          commitCreateRole({
            variables: {
              input: {
                name: values.name,
                description: values.description || null,
                autoAssign: values.autoAssign,
                scope: {
                  scopeType: values.scopeType,
                  scopeId: values.scopeId,
                },
              },
            },
            onCompleted: (_data, errors) => {
              if (errors && errors.length > 0) {
                const errorMessage = errors[0]?.message || '';
                if (isDuplicateError(errorMessage)) {
                  form.setFields([
                    {
                      name: 'name',
                      errors: [t('rbac.DuplicateRoleName')],
                    },
                  ]);
                  return;
                }
                logger.error(errors[0]);
                message.error(errorMessage || t('general.ErrorOccurred'));
                return;
              }
              message.success(t('rbac.RoleCreated'));
              onRequestClose(true);
            },
            onError: (error) => {
              const errorMessage = error?.message || '';
              if (isDuplicateError(errorMessage)) {
                form.setFields([
                  { name: 'name', errors: [t('rbac.DuplicateRoleName')] },
                ]);
              } else {
                logger.error(error);
                message.error(errorMessage || t('general.ErrorOccurred'));
              }
            },
          });
        }
      })
      .catch((err) => logger.error('Validation Failed:', err));
  };

  return (
    <BAIModal
      title={isEditMode ? t('rbac.EditRole') : t('rbac.CreateRole')}
      onOk={handleOk}
      onCancel={() => onRequestClose(false)}
      confirmLoading={isInFlightCreateRole || isInFlightUpdateRole}
      maskClosable={false}
      {...baiModalProps}
    >
      <Form
        form={form}
        layout="vertical"
        requiredMark="optional"
        preserve={false}
        initialValues={{
          name: editingRole?.name ?? '',
          description: editingRole?.description ?? '',
          autoAssign: editingRole?.autoAssign ?? false,
        }}
      >
        <Form.Item
          name="name"
          label={t('rbac.RoleName')}
          rules={[
            {
              required: true,
              message: t('general.ValueRequired', {
                name: t('rbac.RoleName'),
              }),
            },
          ]}
        >
          <AstryxFormTextInput label={t('rbac.RoleName')} hasAutoFocus />
        </Form.Item>
        <Form.Item name="description" label={t('rbac.RoleDescription')}>
          <AstryxFormTextArea label={t('rbac.RoleDescription')} rows={1} />
        </Form.Item>
        <Form.Item
          name="autoAssign"
          label={t('rbac.AutoAssign')}
          valuePropName="checked"
          tooltip={t('rbac.AutoAssignDescription')}
        >
          <AstryxFormCheckbox label={t('general.Enable')} />
        </Form.Item>
        {!isEditMode && (
          <BAIFlex direction="row" gap="xs" align="start">
            <Form.Item
              name="scopeType"
              label={t('rbac.ScopeType')}
              style={{ flex: 1 }}
              rules={[
                {
                  required: true,
                  message: t('general.ValueRequired', {
                    name: t('rbac.ScopeType'),
                  }),
                },
              ]}
            >
              <BAISelect
                showSearch
                placeholder={t('rbac.ScopeType')}
                options={scopeTypeOptions}
                onChange={() => form.setFieldsValue({ scopeId: undefined })}
              />
            </Form.Item>
            <Form.Item
              name="scopeId"
              label={t('rbac.ScopeId')}
              hidden={isDomainScopeType(scopeType)}
              style={{ flex: 1 }}
              rules={[
                {
                  required: true,
                  message: t('general.ValueRequired', {
                    name: t('rbac.ScopeId'),
                  }),
                },
              ]}
            >
              <ScopeIdSelect
                scopeType={scopeType}
                placeholder={t('rbac.ScopeId')}
              />
            </Form.Item>
          </BAIFlex>
        )}
      </Form>
    </BAIModal>
  );
};

export default RoleFormModal;
